324	
325	// ---------- commission_split_tax_line_record (S17) ----------
326	
327	/**
328	 * Insert a tax-attribution row for an existing parent commission split.
329	 * One parent split can have N tax-line children (multi-jurisdiction: state + county + city).
330	 *
331	 * Idempotent on (parent_split_id, tax_line_id) UNIQUE — webhook replay safe.
332	 *
333	 * Caller flow: on payment_intent.succeeded webhook, after recording the parent split,
334	 * iterate Stripe charge.amount_details.tax_breakdown[] and insert one tax-line child
335	 * per breakdown entry. Total tax_amount_cents on parent = sum of children.
336	 */
337	export interface CommissionSplitTaxLineRecordArgs {
338	  parentSplitId: string;
339	  taxLineId: string;                  // Stripe tax_line_xxx OR synthetic if Stripe doesn't provide
340	  jurisdiction: string;               // 'US-NY-NYC', 'GB', etc.
341	  taxAmountCents: CentsAmount;
342	}
343	export type CommissionSplitTaxLineRecordResult = { id: string; created: boolean };
344	
345	// ---------- commission_splits_drift_check (S17) ----------
346	
347	/**
348	 * Reconciliation cron query: detect commission split drift.
349	 * Returns lists of PI ids missing their commission_splits row, AND
350	 * disputes that closed lost without a corresponding reversal row.
351	 *
352	 * Read-only — caller (cron) decides what to do (log + alert vs auto-repair).
353	 */
354	export interface CommissionSplitsDriftCheckArgs {
355	  sinceTimestamp: string;             // ISO timestamptz; only check rows created since
356	}
357	export type CommissionSplitsDriftCheckResult = {
358	  pis_missing_split: Array<{ payment_intent_id: string; charge_id: string | null; studio_id: string; created_at: string }>;
359	  disputes_missing_reversal: Array<{ dispute_id: string; charge_id: string; studio_id: string; resolved_at: string | null }>;
360	  // Sage S17 H1 fix — Leg 3: succeeded charges with tax_amount_cents > 0 but no kind='tax_line' children.
361	  // Detects silent loss of tax_line attribution → quarterly remittance miscount.
362	  charges_missing_tax_line: Array<{ payment_intent_id: string; charge_id: string | null; studio_id: string; tax_amount_cents: CentsAmount }>;
363	  // S18 Leg 4: refunds that reversed parent split but missed tax_line proportional reversal.
364	  // Detects under-reversed tax accrual → tax remittance ledger stays accrued for already-refunded amounts.
365	  refunds_missing_tax_reversal: Array<{ refund_id: string; payment_intent_id: string; studio_id: string; missing_jurisdictions: string[] }>;
366	};
367	
368	// ---------- commission_split_tax_line_reverse (S18) ----------
369	
370	/**
371	 * Refund-driven reversal of a tax_line attribution row.
372	 *
373	 * Inserts a NEW commission_splits row with kind='reversal' and parent_split_id
374	 * pointing at the tax_line row being reversed. Negative tax_amount_cents
375	 * indicates the reversal direction.
376	 *
377	 * Idempotent on (parent_tax_line_split_id, refund_id) — replay safe.
